﻿/* ui.js - wiring for the doc-template-styler editor. All model edits go through
   here; rendering is delegated to core.js so the editor and the CLI agree. */
(function () {
  'use strict';

  var C = window.DocStylerCore;
  var PALETTES = window.DOC_STYLER_PALETTES || {};
  var BUILTINS = window.DOC_STYLER_BUILTINS || [];
  var KEY = 'doc-styler-editor-v1';
  var VAR_NAMES = ['--brand-primary', '--brand-accent', '--brand-ink', '--doc-bg', '--doc-surface'];

  function $(id) { return document.getElementById(id); }

  function el(tag, attrs, kids) {
    var node = document.createElement(tag);
    Object.keys(attrs || {}).forEach(function (k) {
      var v = attrs[k];
      if (v === null || v === undefined || v === false) return;
      if (k === 'class') node.className = v;
      else if (k === 'text') node.textContent = v;
      else if (k.slice(0, 2) === 'on' && typeof v === 'function') node.addEventListener(k.slice(2), v);
      else node.setAttribute(k, v);
    });
    (kids || []).forEach(function (c) {
      if (c === null || c === undefined) return;
      node.appendChild(typeof c === 'string' ? document.createTextNode(c) : c);
    });
    return node;
  }

  function asPair(v) {
    if (C.isDual(v)) return { vi: v.vi === undefined ? '' : v.vi, en: v.en === undefined ? '' : v.en };
    return { vi: v === null || v === undefined ? '' : String(v), en: '' };
  }
  function pairText(p) { return (p.vi || p.en || '').trim(); }

  function lines(pairs, lang) {
    return (pairs || []).map(function (p) { return asPair(p)[lang] || ''; }).join('\n');
  }
  function fromLines(viText, enText) {
    var a = String(viText || '').split('\n'), b = String(enText || '').split('\n');
    var n = Math.max(a.length, b.length), out = [];
    for (var i = 0; i < n; i++) {
      var vi = (a[i] === undefined ? '' : a[i]);
      var en = (b[i] === undefined ? '' : b[i]);
      if (!vi.trim() && !en.trim()) continue;
      out.push({ vi: vi, en: en });
    }
    return out;
  }
  function splitCells(line) { return line.split('|').map(function (s) { return s.trim(); }); }

  function merge(target, source) {
    Object.keys(source || {}).forEach(function (k) { target[k] = source[k]; });
    return target;
  }

  /* ------------------------------------------------------------- state ---- */

  var state = null;

  function emptyModel() {
    return C.normalizeModel({
      title: { vi: '', en: '' }, subtitle: { vi: '', en: '' }, date: '', doc_type: 'report', brand: '',
      lang: 'vi', sections: [{ heading: { vi: 'Mục 1', en: 'Section 1' }, level: 2,
        blocks: [{ type: 'paragraph', text: { vi: '', en: '' } }] }]
    });
  }

  /* A palette map entry without .modes would otherwise take the whole editor
     down at start-up, so every consumer checks the shape first. */
  function usablePalettes() {
    return Object.keys(PALETTES).filter(function (k) {
      return PALETTES[k] && PALETTES[k].modes && PALETTES[k].modes.dark && PALETTES[k].modes.light;
    });
  }

  function firstPaletteName() { return usablePalettes()[0] || '__custom'; }

  function blankState() {
    var p0 = PALETTES[firstPaletteName()];
    var custom = p0 ? { dark: merge({}, p0.modes.dark), light: merge({}, p0.modes.light) } : { dark: {}, light: {} };
    return {
      model: emptyModel(),
      bilingual: true,
      templates: BUILTINS.slice(),
      templateId: BUILTINS.length ? BUILTINS[0].id : '',
      palette: firstPaletteName(),
      custom: custom,
      mode: (p0 && p0.default_mode) || 'dark',
      initial: '',
      width: 0,
      zoom: 1,
      open: [true],
      lastHtml: ''
    };
  }

  function save() {
    try {
      localStorage.setItem(KEY, JSON.stringify({
        model: state.model, bilingual: state.bilingual, templateId: state.templateId,
        palette: state.palette, custom: state.custom, mode: state.mode, initial: state.initial
      }));
    } catch (e) { /* file:// or private mode - not worth failing the edit over */ }
  }

  function restore() {
    var raw = null;
    try { raw = localStorage.getItem(KEY); } catch (e) { return false; }
    if (!raw) return false;
    try {
      var s = JSON.parse(raw);
      if (!s || !s.model) return false;
      state.model = C.normalizeModel(s.model);
      state.bilingual = !!s.bilingual;
      state.palette = s.palette || state.palette;
      if (s.custom && s.custom.dark) state.custom = s.custom;
      state.mode = s.mode === 'light' ? 'light' : 'dark';
      state.initial = s.initial || '';
      if (s.templateId) state.templateId = s.templateId;
      state.open = state.model.sections.map(function () { return true; });
      if (!state.open.length) state.open = [true];
      return true;
    } catch (e) { return false; }
  }

  function findTemplate(id) {
    for (var i = 0; i < state.templates.length; i++) {
      if (state.templates[i].id === id) return state.templates[i];
    }
    return null;
  }

  function activePalette() {
    if (state.palette === '__custom') {
      return { label: 'Custom', default_mode: state.mode, modes: state.custom };
    }
    var p = PALETTES[state.palette];
    return (p && p.modes) ? p : null;
  }

  function buildDoc() {
    var tpl = findTemplate(state.templateId);
    if (!tpl) return { html: '<!DOCTYPE html><p style="font:16px system-ui;padding:24px">No template selected.</p>' };
    return C.fillTemplate(tpl.html, state.model, {
      palette: activePalette(),
      theme: state.initial || undefined,
      bilingual: state.bilingual
    });
  }

  /* ------------------------------------------------------------ preview --- */

  var previewTimer = null;
  function renderPreview(now) {
    clearTimeout(previewTimer);
    /* now=true paints synchronously, which the self test and first load rely
       on; typing goes through the debounce so the iframe is not rebuilt on
       every keystroke. */
    var paint = function () {
      var out = buildDoc();
      state.lastHtml = out.html;
      $('previewFrame').srcdoc = out.html;
      $('previewInfo').textContent = out.sections + ' mục · ' + (out.bilingual ? 'VI+EN' : out.lang)
        + ' · ' + (state.palette === '__custom' ? 'màu tự chọn' : state.palette);
    };
    if (now) paint(); else previewTimer = setTimeout(paint, 220);
  }

  /* --------------------------------------------------------- form pieces -- */

  function field(label, input) {
    return el('label', { class: 'f' }, [el('span', { text: label }), input]);
  }

  function textInput(value, onChange, placeholder) {
    return el('input', { type: 'text', value: value || '', placeholder: placeholder || '',
      oninput: function () { onChange(this.value); } });
  }

  function textArea(value, onChange, rows, placeholder) {
    return el('textarea', { rows: rows || 4, placeholder: placeholder || '', spellcheck: 'false',
      oninput: function () { onChange(this.value); } }, [value || '']);
  }

  /* One logical text field. With bilingual on, VI and EN sit side by side and
     both are always stored, so switching the switch off never drops a language. */
  function pairField(labelText, value, onChange, multiline, rows, placeholder) {
    var p = asPair(value);
    var vi = multiline ? textArea(p.vi, function (v) { p.vi = v; onChange(p); }, rows, placeholder)
                       : textInput(p.vi, function (v) { p.vi = v; onChange(p); }, placeholder);
    var viField = field(labelText + ' (VI)', vi);
    if (!state.bilingual) return viField;
    var en = multiline ? textArea(p.en, function (v) { p.en = v; onChange(p); }, rows, placeholder)
                       : textInput(p.en, function (v) { p.en = v; onChange(p); }, placeholder);
    return el('div', { class: 'row2' }, [viField, field(labelText + ' (EN)', en)]);
  }

  /* ------------------------------------------------------- block editor --- */

  var BLOCK_TYPES = ['paragraph', 'heading', 'list', 'table', 'callout', 'kv', 'quote', 'hr'];

  function newBlock(type) {
    if (type === 'list') return { type: 'list', ordered: false, items: [{ vi: '', en: '' }] };
    if (type === 'table') return { type: 'table', headers: [{ vi: '', en: '' }], rows: [[{ vi: '', en: '' }]] };
    if (type === 'callout') return { type: 'callout', tone: 'info', title: { vi: '', en: '' }, text: { vi: '', en: '' } };
    if (type === 'kv') return { type: 'kv', pairs: [[{ vi: '', en: '' }, { vi: '', en: '' }]] };
    if (type === 'hr') return { type: 'hr' };
    if (type === 'heading') return { type: 'heading', text: { vi: '', en: '' }, level: 3 };
    return { type: 'paragraph', text: { vi: '', en: '' } };
  }

  /* Switching a block's type keeps the text already typed, so a mis-picked
     type is a one-click fix rather than a re-entry. */
  function convertBlock(block, type) {
    var fresh = newBlock(type);
    var carry = asPair(block.text !== undefined ? block.text : block.title);
    if (fresh.text !== undefined) fresh.text = { vi: carry.vi, en: carry.en };
    if (fresh.title !== undefined) fresh.title = { vi: carry.vi, en: carry.en };
    if (fresh.items && (block.items || []).length) fresh.items = block.items;
    if (fresh.headers && (block.headers || []).length) fresh.headers = block.headers;
    if (fresh.rows && (block.rows || []).length) fresh.rows = block.rows;
    if (fresh.pairs && (block.pairs || []).length) fresh.pairs = block.pairs;
    if (fresh.ordered !== undefined) fresh.ordered = !!block.ordered;
    if (block.tone) fresh.tone = block.tone;
    return fresh;
  }

  function blockBody(block) {
    var wrap = el('div', {});
    var touch = function () { scheduleSave(); renderPreview(); };

    if (block.type === 'hr') {
      wrap.appendChild(el('p', { class: 'hint', text: 'Đường kẻ ngang — không có nội dung.' }));
      return wrap;
    }
    if (block.type === 'heading') {
      wrap.appendChild(pairField('Tiêu đề phụ', block.text, function (p) { block.text = p; touch(); }));
      var sel = el('select', { onchange: function () { block.level = parseInt(this.value, 10); touch(); } },
        [3, 4, 5, 6].map(function (n) { return el('option', { value: n, text: 'Cấp ' + n }); }));
      sel.value = String(block.level || 3);
      wrap.appendChild(field('Cấp tiêu đề', sel));
      return wrap;
    }
    if (block.type === 'list') {
      var chk = el('input', { type: 'checkbox', onchange: function () { block.ordered = this.checked; touch(); } });
      if (block.ordered) chk.checked = true;
      wrap.appendChild(el('label', { class: 'f' }, [el('span', { text: 'Kiểu danh sách' }),
        el('span', { class: 'mini' }, [chk, el('span', { text: ' Đánh số (1, 2, 3)' })])]));
      wrap.appendChild(pairField('Mỗi dòng một mục', { vi: lines(block.items, 'vi'), en: lines(block.items, 'en') },
        function (p) { block.items = fromLines(p.vi, p.en); touch(); }, true, 4, 'Dòng 1'));
      return wrap;
    }
    if (block.type === 'table') {
      wrap.appendChild(pairField('Hàng tiêu đề (mỗi dòng một ô)',
        { vi: lines(block.headers, 'vi'), en: lines(block.headers, 'en') },
        function (p) { block.headers = fromLines(p.vi, p.en); touch(); }, true, 2));
      var rowsVi = (block.rows || []).map(function (r) { return r.map(function (c) { return asPair(c).vi; }).join(' | '); }).join('\n');
      var rowsEn = (block.rows || []).map(function (r) { return r.map(function (c) { return asPair(c).en; }).join(' | '); }).join('\n');
      wrap.appendChild(pairField('Hàng dữ liệu (mỗi dòng một hàng, ô cách nhau bằng |)',
        { vi: rowsVi, en: rowsEn }, function (p) {
          var a = p.vi.split('\n'), b = p.en.split('\n');
          var n = Math.max(a.length, b.length), out = [];
          for (var i = 0; i < n; i++) {
            if (!a[i] && !b[i]) continue;
            var ca = splitCells(a[i] === undefined ? '' : a[i]);
            var cb = splitCells(b[i] === undefined ? '' : b[i]);
            var width = Math.max(ca.length, cb.length), row = [];
            for (var j = 0; j < width; j++) {
              row.push({ vi: ca[j] === undefined ? '' : ca[j], en: cb[j] === undefined ? '' : cb[j] });
            }
            out.push(row);
          }
          block.rows = out; touch();
        }, true, 4, 'Doanh thu | 48,2'));
      return wrap;
    }
    if (block.type === 'callout') {
      var tone = el('select', { onchange: function () { block.tone = this.value; touch(); } },
        ['info', 'warn', 'success'].map(function (t) { return el('option', { value: t, text: t }); }));
      tone.value = block.tone || 'info';
      wrap.appendChild(field('Loại', tone));
      wrap.appendChild(pairField('Tiêu đề', block.title, function (p) { block.title = p; touch(); }));
      wrap.appendChild(pairField('Nội dung', block.text, function (p) { block.text = p; touch(); }, true, 3));
      return wrap;
    }
    if (block.type === 'kv') {
      var kvVi = (block.pairs || []).map(function (p) { return asPair(p[0]).vi + ' | ' + asPair(p[1]).vi; }).join('\n');
      var kvEn = (block.pairs || []).map(function (p) { return asPair(p[0]).en + ' | ' + asPair(p[1]).en; }).join('\n');
      wrap.appendChild(pairField('Mỗi dòng: khoá | giá trị', { vi: kvVi, en: kvEn }, function (p) {
        var a = p.vi.split('\n'), b = p.en.split('\n');
        var n = Math.max(a.length, b.length), out = [];
        for (var i = 0; i < n; i++) {
          if (!a[i] && !b[i]) continue;
          var ka = splitCells(a[i] === undefined ? '' : a[i]);
          var kb = splitCells(b[i] === undefined ? '' : b[i]);
          out.push([
            { vi: ka[0] === undefined ? '' : ka[0], en: kb[0] === undefined ? '' : kb[0] },
            { vi: ka[1] === undefined ? '' : ka[1], en: kb[1] === undefined ? '' : kb[1] }
          ]);
        }
        block.pairs = out; touch();
      }, true, 3));
      return wrap;
    }
    wrap.appendChild(pairField('Nội dung', block.text, function (p) { block.text = p; touch(); }, true, 4));
    return wrap;
  }

  function blockCard(section, bi) {
    var block = section.blocks[bi];
    var move = function (delta) {
      var to = bi + delta;
      if (to < 0 || to >= section.blocks.length) return;
      var tmp = section.blocks[bi];
      section.blocks[bi] = section.blocks[to];
      section.blocks[to] = tmp;
      scheduleSave(); renderSections(); renderPreview();
    };
    var sel = el('select', { onchange: function () {
      section.blocks[bi] = convertBlock(block, this.value);
      scheduleSave(); renderSections(); renderPreview();
    } }, BLOCK_TYPES.map(function (t) { return el('option', { value: t, text: t }); }));
    sel.value = block.type;

    var head = el('div', { class: 'hd' }, [
      sel,
      el('span', { class: 'grow' }),
      el('button', { class: 'btn tiny', text: '\u2191', title: 'Lên', onclick: function () { move(-1); } }),
      el('button', { class: 'btn tiny', text: '\u2193', title: 'Xuống', onclick: function () { move(1); } }),
      el('button', { class: 'btn tiny', text: '\u2715', title: 'Xoá block', onclick: function () {
        section.blocks.splice(bi, 1);
        scheduleSave(); renderSections(); renderPreview();
      } })
    ]);
    return el('div', { class: 'blk' }, [head, blockBody(block)]);
  }

  function sectionCard(section, si) {
    var titleNode = el('span', { class: 't', text: pairText(asPair(section.heading)) || '(chưa có tiêu đề)' });

    function move(delta) {
      var to = si + delta;
      if (to < 0 || to >= state.model.sections.length) return;
      var tmp = state.model.sections[si];
      state.model.sections[si] = state.model.sections[to];
      state.model.sections[to] = tmp;
      var t = state.open[si]; state.open[si] = state.open[to]; state.open[to] = t;
      scheduleSave(); renderSections(); renderPreview();
    }

    var card = el('div', { class: 'sec' + (state.open[si] ? ' open' : '') });
    var head = el('div', { class: 'hd', onclick: function (e) {
      if (e.target.closest('button') || e.target.closest('select')) return;
      state.open[si] = !state.open[si];
      card.className = 'sec' + (state.open[si] ? ' open' : '');
    } }, [
      el('span', { class: 'n', text: String(si + 1) }),
      titleNode,
      el('span', { class: 'mini' }, [
        el('button', { class: 'btn tiny', text: '\u2191', title: 'Lên', onclick: function () { move(-1); } }),
        el('button', { class: 'btn tiny', text: '\u2193', title: 'Xuống', onclick: function () { move(1); } }),
        el('button', { class: 'btn tiny', text: '\u2715', title: 'Xoá mục', onclick: function () {
          state.model.sections.splice(si, 1);
          state.open.splice(si, 1);
          scheduleSave(); renderSections(); renderPreview();
        } })
      ])
    ]);

    var levelSel = el('select', { onchange: function () { section.level = parseInt(this.value, 10); scheduleSave(); renderPreview(); } },
      [2, 3].map(function (n) { return el('option', { value: n, text: 'Cấp ' + n }); }));
    levelSel.value = String(section.level || 2);

    var addSel = el('select', {}, [el('option', { value: '', text: '+ Thêm block…' })]
      .concat(BLOCK_TYPES.map(function (t) { return el('option', { value: t, text: t }); })));
    addSel.addEventListener('change', function () {
      if (!this.value) return;
      section.blocks.push(newBlock(this.value));
      this.value = '';
      scheduleSave(); renderSections(); renderPreview();
    });

    var body = el('div', { class: 'bd' }, [
      pairField('Tiêu đề mục', section.heading, function (p) {
        section.heading = p;
        titleNode.textContent = pairText(p) || '(chưa có tiêu đề)';
        scheduleSave(); renderPreview();
      }),
      field('Cấp tiêu đề', levelSel),
      el('div', {}, section.blocks.map(function (_, bi) { return blockCard(section, bi); })),
      addSel
    ]);

    card.appendChild(head);
    card.appendChild(body);
    return card;
  }

  function renderSections() {
    var host = $('sections');
    host.textContent = '';
    state.model.sections.forEach(function (section, si) { host.appendChild(sectionCard(section, si)); });
    if (!state.model.sections.length) {
      host.appendChild(el('p', { class: 'empty', text: 'Chưa có mục nào — bấm "+ Thêm mục".' }));
    }
  }

  /* ------------------------------------------------------------ meta bar -- */

  function renderMeta() {
    $('m-title-vi').value = asPair(state.model.title).vi;
    $('m-title-en').value = asPair(state.model.title).en;
    $('m-subtitle-vi').value = asPair(state.model.subtitle).vi;
    $('m-subtitle-en').value = asPair(state.model.subtitle).en;
    $('m-date').value = C.plain(state.model.date) || '';
    $('m-lang').value = C.plain(state.model.lang) || 'vi';
    $('m-bilingual').value = state.bilingual ? 'true' : 'false';
    $('wrap-title-en').style.display = state.bilingual ? '' : 'none';
    $('wrap-subtitle-en').style.display = state.bilingual ? '' : 'none';
    var filled = 0, total = 0;
    (function walk(v) {
      if (C.isDual(v)) { total++; if (String(v.en || '').trim()) filled++; return; }
      if (Array.isArray(v)) { v.forEach(walk); return; }
      if (v && typeof v === 'object') { Object.keys(v).forEach(function (k) { walk(v[k]); }); return; }
    })(state.model);
    $('bilingualHint').textContent = state.bilingual
      ? (filled + '/' + total + ' trường đã có bản EN. Bật song ngữ mà để trống EN sẽ thấy ô rỗng khi bấm nút EN.')
      : 'Đang tắt song ngữ: file xuất ra chỉ hiển thị một ngôn ngữ (theo "Ngôn ngữ mở đầu").';
  }

  function wireMeta() {
    var title = asPair(state.model.title), sub = asPair(state.model.subtitle);
    $('m-title-vi').addEventListener('input', function () { title.vi = this.value; state.model.title = title; scheduleSave(); renderPreview(); });
    $('m-title-en').addEventListener('input', function () { title.en = this.value; state.model.title = title; scheduleSave(); renderPreview(); });
    $('m-subtitle-vi').addEventListener('input', function () { sub.vi = this.value; state.model.subtitle = sub; scheduleSave(); renderPreview(); });
    $('m-subtitle-en').addEventListener('input', function () { sub.en = this.value; state.model.subtitle = sub; scheduleSave(); renderPreview(); });
    $('m-date').addEventListener('input', function () { state.model.date = this.value; scheduleSave(); renderPreview(); });
    $('m-doctype').addEventListener('change', function () { state.model.doc_type = this.value; scheduleSave(); renderPreview(); });
    $('m-lang').addEventListener('change', function () { state.model.lang = this.value; scheduleSave(); renderPreview(); });
    $('m-bilingual').addEventListener('change', function () {
      state.bilingual = this.value === 'true';
      scheduleSave(); renderMeta(); renderSections(); renderPreview();
    });
  }

  /* --------------------------------------------------------- templates ---- */

  function templateChips(tpl) {
    var info = tpl.info || C.inspectTemplate(tpl.html);
    tpl.info = info;
    var chips = [];
    if (tpl.builtin) chips.push({ text: 'có sẵn', cls: 'chip acc' });
    if (tpl.adapted) chips.push({ text: 'đã tự chuyển đổi', cls: 'chip' });
    if (!info.hasBody) chips.push({ text: 'thiếu {{body}}', cls: 'chip no' });
    if (!info.themeable) chips.push({ text: 'màu cố định', cls: 'chip no' });
    if (!chips.length) chips.push({ text: info.placeholders.length + ' placeholder', cls: 'chip ok' });
    return chips;
  }

  function renderTemplates() {
    var host = $('templates');
    host.textContent = '';
    state.templates.forEach(function (tpl) {
      var frame = el('iframe', { sandbox: '', title: tpl.label });
      var thumb = el('div', { class: 'th' }, [frame]);
      var card = el('div', {
        class: 'tpl' + (tpl.id === state.templateId ? ' on' : ''),
        onclick: function () { selectTemplate(tpl.id); }
      }, [
        thumb,
        el('div', { class: 'nm' }, [el('span', { text: tpl.label })]),
        el('div', { class: 'desc', text: tpl.description || tpl.use_when || '' }),
        el('div', { class: 'mini' }, templateChips(tpl).map(function (c) { return el('span', { class: c.cls, text: c.text }); }))
      ]);
      card.dataset.tplId = tpl.id;
      host.appendChild(card);

      var pal = PALETTES[tpl.default_palette] || activePalette();
      frame.srcdoc = C.fillTemplate(tpl.html, C.sampleModel(), { palette: pal, bilingual: true }).html;
      requestAnimationFrame(function () {
        var scale = (thumb.clientWidth || 260) / 1000;
        frame.style.transform = 'scale(' + scale + ')';
      });
    });
    $('tplHint').textContent = 'Template nhập vào chỉ sống trong phiên làm việc này; '
      + 'chỉ template có sẵn trong skill là tự nạp lại sau khi tải trang.';
  }

  function selectTemplate(id) {
    state.templateId = id;
    Array.prototype.forEach.call($('templates').children, function (card) {
      card.className = 'tpl' + (card.dataset.tplId === id ? ' on' : '');
    });
    var tpl = findTemplate(id);
    if (tpl) {
      var info = tpl.info || C.inspectTemplate(tpl.html);
      if (!info.themeable) toast('Template "' + tpl.label + '" không dùng 5 biến --brand-*, nên bộ màu bên dưới sẽ không áp dụng.');
    }
    scheduleSave(); renderPreview(true);
  }

  /* ------------------------------------------------------------ colours -- */

  function renderPalettes() {
    var host = $('paletteChips');
    host.textContent = '';
    usablePalettes().forEach(function (name) {
      var p = PALETTES[name];
      var bars = el('div', { class: 'bars' }, [
        el('i', { style: 'background:' + p.modes.dark['--doc-bg'] }),
        el('i', { style: 'background:' + p.modes.dark['--brand-primary'] }),
        el('i', { style: 'background:' + p.modes.light['--doc-bg'] }),
        el('i', { style: 'background:' + p.modes.light['--brand-primary'] })
      ]);
      host.appendChild(el('div', {
        class: 'sw' + (state.palette === name ? ' on' : ''),
        onclick: function () {
          state.palette = name;
          state.mode = p.default_mode || 'dark';
          state.custom = { dark: merge({}, p.modes.dark), light: merge({}, p.modes.light) };
          scheduleSave(); renderPalettes(); renderColors(); renderPreview(true);
        }
      }, [bars, el('div', { class: 'lbl', text: p.label }), el('div', { class: 'sub', text: name })]));
    });

    host.appendChild(el('div', {
      class: 'sw' + (state.palette === '__custom' ? ' on' : ''),
      onclick: function () { state.palette = '__custom'; scheduleSave(); renderPalettes(); renderColors(); renderPreview(true); }
    }, [
      el('div', { class: 'bars' }, [
        el('i', { style: 'background:' + (state.custom.dark['--doc-bg'] || '#000') }),
        el('i', { style: 'background:' + (state.custom.dark['--brand-primary'] || '#888') }),
        el('i', { style: 'background:' + (state.custom.light['--doc-bg'] || '#fff') }),
        el('i', { style: 'background:' + (state.custom.light['--brand-primary'] || '#888') })
      ]),
      el('div', { class: 'lbl', text: 'Tuỳ chỉnh' }),
      el('div', { class: 'sub', text: 'tự nhập màu' })
    ]));
  }

  function toHex(v) {
    var rgb = C.hexToRgb(v);
    return rgb ? C.rgbToHex(rgb) : '#000000';
  }

  function setVar(name, value) {
    state.custom[state.mode] = state.custom[state.mode] || {};
    state.custom[state.mode][name] = value;
    if (state.palette !== '__custom') { state.palette = '__custom'; renderPalettes(); }
    scheduleSave(); renderPreview();
  }

  function renderColors() {
    var host = $('colorVars');
    host.textContent = '';
    var vars = state.custom[state.mode] || {};
    VAR_NAMES.forEach(function (name) {
      var colour = el('input', { type: 'color', value: toHex(vars[name]), oninput: function () {
        setVar(name, this.value); } });
      var text = el('input', { type: 'text', value: toHex(vars[name]), oninput: function () {
        if (C.hexToRgb(this.value)) { setVar(name, this.value); colour.value = toHex(this.value); }
      } });
      host.appendChild(el('div', { class: 'cvar' }, [
        el('span', { class: 'nm', text: name }),
        el('span', { class: 'ctl' }, [colour, text])
      ]));
    });
    Array.prototype.forEach.call($('segMode').children, function (b) {
      b.className = b.dataset.m === state.mode ? 'on' : '';
    });
  }

  function otherMode() { return state.mode === 'dark' ? 'light' : 'dark'; }

  /* ------------------------------------------------------------- import -- */

  function importTemplateFile(file) {
    var reader = new FileReader();
    reader.onload = function () {
      var html = String(reader.result);
      var info = C.inspectTemplate(html);
      var adapted = false;
      if (!info.hasBody) { html = C.adaptTemplate(html); adapted = true; info = C.inspectTemplate(html); }
      var id = 'user-' + file.name.replace(/\.[^.]+$/, '').replace(/[^A-Za-z0-9_-]+/g, '-');
      state.templates = state.templates.filter(function (t) { return t.id !== id; });
      state.templates.push({
        id: id, label: file.name,
        description: info.themeable ? 'Template nhập từ file — ' + info.placeholders.length + ' placeholder'
                                   : 'Template nhập từ file — không dùng biến --brand-*',
        default_palette: state.palette === '__custom' ? null : state.palette,
        html: html, info: info, adapted: adapted
      });
      state.templateId = id;
      renderTemplates(); scheduleSave(); renderPreview(true);
      toast('Đã nhập template "' + file.name + '"' + (adapted ? ' (tự thêm {{body}} và style block).' : '.'));
    };
    reader.readAsText(file);
  }

  function importDocument(file) {
    var reader = new FileReader();
    reader.onload = function () {
      var text = String(reader.result);
      var ext = (file.name.split('.').pop() || '').toLowerCase();
      var model;
      try {
        if (ext === 'json') model = C.parseJsonModel(text);
        else if (ext === 'html' || ext === 'htm') model = C.parseHtmlDoc(new DOMParser().parseFromString(text, 'text/html'));
        else model = C.parseMarkdown(text);
      } catch (e) {
        toast('Không đọc được tài liệu: ' + e.message, true);
        return;
      }
      state.model = C.normalizeModel(model);
      state.bilingual = C.hasDual(state.model);
      state.open = state.model.sections.map(function () { return true; });
      if (!state.open.length) state.open = [true];
      var want = state.model.doc_type;
      var match = state.templates.filter(function (t) { return (t.doc_types || []).indexOf(want) >= 0; });
      if (match.length) state.templateId = match[0].id;
      renderMeta(); renderSections(); renderTemplates(); renderColors(); renderPreview(true); scheduleSave();
      toast('Đã nhập "' + file.name + '": ' + state.model.sections.length + ' mục, loại "' + want + '"');
    };
    reader.readAsText(file);
  }

  /* ------------------------------------------------------------ helpers -- */

  var saveTimer = null;
  function scheduleSave() {
    clearTimeout(saveTimer);
    saveTimer = setTimeout(save, 400);
  }

  var toastTimer = null;
  function toast(message, isError) {
    var t = $('toast');
    t.textContent = message;
    t.className = 'on' + (isError ? ' err' : '');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { t.className = ''; }, isError ? 7000 : 4200);
  }

  function download(name, text, mime) {
    var url = URL.createObjectURL(new Blob([text], { type: mime }));
    var a = el('a', { href: url, download: name });
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(function () { URL.revokeObjectURL(url); }, 5000);
  }

  function outputName(ext) {
    return C.slug(pairText(asPair(state.model.title)) || 'tai-lieu').slice(0, 60) + ext;
  }

  /* ---------------------------------------------------------- self test -- */

  function selfTest() {
    var results = [];
    function check(name, fn) {
      try { var r = fn(); results.push((r === true ? 'PASS' : 'FAIL') + '  ' + name + (r === true ? '' : ' -> ' + r)); }
      catch (e) { results.push('FAIL  ' + name + ' -> ' + e.message); }
    }
    check('core loaded', function () { return !!C || 'DocStylerCore missing'; });
    check('builtin templates embedded', function () { return BUILTINS.length >= 2 || 'found ' + BUILTINS.length; });
    check('palettes embedded', function () { return Object.keys(PALETTES).length >= 5 || 'found ' + Object.keys(PALETTES).length; });
    BUILTINS.forEach(function (tpl) {
      check('render ' + tpl.id, function () {
        var out = C.fillTemplate(tpl.html, C.sampleModel(), { palette: PALETTES[tpl.default_palette] });
        if (out.leftover.length) return 'unfilled ' + out.leftover.join(',');
        if (out.html.indexOf('doc-section') < 0) return 'no doc-section in output';
        if (out.html.indexOf('palette-override') < 0) return 'no palette injected';
        if (out.html.indexOf('{{') >= 0) return 'leftover {{ in output';
        return true;
      });
    });
    check('markdown table parses', function () {
      var m = C.parseMarkdown('# T\n\n| A | B |\n|---|---|\n| 1 | 2 |\n');
      return m.sections[0].blocks[0].type === 'table' || 'got ' + m.sections[0].blocks[0].type;
    });
    check('markdown list parses', function () {
      var b = C.parseMarkdown('# T\n\n- a\n- b\n').sections[0].blocks[0];
      return (b.type === 'list' && b.items.length === 2) || 'got ' + JSON.stringify(b);
    });
    check('palette override beats template light fallback', function () {
      var out = C.fillTemplate(BUILTINS[0].html, C.sampleModel(), { palette: PALETTES['warm-earth'], theme: 'light' });
      var i = out.html.indexOf('palette-override');
      var seg = out.html.slice(i, i + 900);
      if (seg.indexOf('html[data-theme="light"]') < 0) return 'no light attribute rule';
      if (seg.indexOf('html[data-theme="dark"]') < 0) return 'no dark attribute rule';
      return true;
    });
    check('custom palette reaches the output', function () {
      var pal = { default_mode: 'dark', modes: { dark: { '--brand-primary': '#ff0000' }, light: { '--brand-primary': '#00ff00' } } };
      var out = C.fillTemplate(BUILTINS[0].html, C.sampleModel(), { palette: pal, theme: 'dark' });
      return out.html.indexOf('#ff0000') >= 0 || 'custom colour missing from output';
    });
    check('structure editor is live', function () {
      return (!!state && state.model.sections.length > 0) || 'no sections in state';
    });
    check('preview frame rendered', function () {
      var f = $('previewFrame');
      return (f && f.srcdoc && f.srcdoc.indexOf('doc-section') >= 0) || 'preview srcdoc empty';
    });
    var failed = results.filter(function (r) { return r.indexOf('PASS') !== 0; }).length;
    document.body.dataset.selftest = failed ? 'FAIL' : 'PASS';
    document.title = (failed ? 'FAIL ' : 'PASS ') + 'doc-styler-editor self test';
    document.body.appendChild(el('pre', { id: 'selftest', style: 'position:fixed;inset:10px;z-index:999;'
      + 'overflow:auto;background:#000;color:#0f0;font:12px/1.5 monospace;padding:16px;margin:0' },
      [results.join('\n') + '\n\n' + (failed ? failed + ' FAILED' : 'ALL PASS')]));
  }

  /* --------------------------------------------------------------- boot -- */

  function boot() {
    C.DOC_TYPES.forEach(function (t) { $('m-doctype').appendChild(el('option', { value: t, text: t })); });

    var restored = restore();
    state.templates = BUILTINS.slice();
    if (!findTemplate(state.templateId)) state.templateId = BUILTINS.length ? BUILTINS[0].id : '';
    if (!state.model.sections.length) {
      state.model.sections = [{ heading: { vi: 'Mục 1', en: 'Section 1' }, level: 2, blocks: [newBlock('paragraph')] }];
      state.open = [true];
    }
    if (!state.open.length || state.open.length !== state.model.sections.length) {
      state.open = state.model.sections.map(function () { return true; });
    }

    wireMeta();
    renderMeta();
    renderSections();
    renderTemplates();
    renderPalettes();
    renderColors();
    renderPreview(true);

    $('btnAddSection').addEventListener('click', function () {
      var n = state.model.sections.length + 1;
      state.model.sections.push({ heading: { vi: 'Mục ' + n, en: 'Section ' + n }, level: 2,
        blocks: [newBlock('paragraph')] });
      state.open.push(true);
      scheduleSave(); renderSections(); renderPreview();
    });

    $('btnExportHtml').addEventListener('click', function () {
      var tpl = findTemplate(state.templateId);
      var info = tpl ? (tpl.info || C.inspectTemplate(tpl.html)) : null;
      if (info && !info.hasBody) toast('Template này thiếu {{body}} — nội dung có thể không xuất hiện.', true);
      download(outputName('.html'), buildDoc().html, 'text/html;charset=utf-8');
      toast('Đã tải ' + outputName('.html'));
    });
    $('btnExportJson').addEventListener('click', function () {
      download(outputName('.json'), JSON.stringify(state.model, null, 2), 'application/json;charset=utf-8');
      toast('Đã tải model JSON');
    });
    $('btnOpenTab').addEventListener('click', function () {
      var url = URL.createObjectURL(new Blob([buildDoc().html], { type: 'text/html;charset=utf-8' }));
      window.open(url, '_blank');
      setTimeout(function () { URL.revokeObjectURL(url); }, 30000);
    });
    $('btnReset').addEventListener('click', function () {
      if (!window.confirm('Xoá toàn bộ nội dung đang soạn và bắt đầu lại?')) return;
      try { localStorage.removeItem(KEY); } catch (e) {}
      state = blankState();
      renderMeta(); renderSections(); renderTemplates(); renderPalettes(); renderColors(); renderPreview(true);
      toast('Đã làm mới.');
    });
    $('btnLoadSample').addEventListener('click', function () {
      state.model = C.normalizeModel(C.sampleModel());
      state.bilingual = true;
      state.open = state.model.sections.map(function () { return true; });
      renderMeta(); renderSections(); renderPreview(true); scheduleSave();
      toast('Đã nạp dữ liệu mẫu.');
    });
    $('btnImport').addEventListener('click', function () { $('fileDoc').click(); });
    $('fileDoc').addEventListener('change', function () {
      if (this.files[0]) importDocument(this.files[0]);
      this.value = '';
    });
    $('btnImportTpl').addEventListener('click', function () { $('fileTpl').click(); });
    $('fileTpl').addEventListener('change', function () {
      Array.prototype.forEach.call(this.files, importTemplateFile);
      this.value = '';
    });

    Array.prototype.forEach.call($('segWidth').children, function (b) {
      b.addEventListener('click', function () {
        state.width = parseInt(b.dataset.w, 10);
        Array.prototype.forEach.call($('segWidth').children, function (x) { x.className = x === b ? 'on' : ''; });
        $('previewFrame').style.maxWidth = state.width ? state.width + 'px' : '';
      });
    });
    Array.prototype.forEach.call($('segMode').children, function (b) {
      b.addEventListener('click', function () { state.mode = b.dataset.m; renderColors(); renderPreview(true); });
    });
    $('selZoom').addEventListener('change', function () { $('previewFrame').style.zoom = parseFloat(this.value); });
    $('selInitial').addEventListener('change', function () {
      state.initial = this.value; scheduleSave(); renderPreview(true);
    });
    $('btnDerive').addEventListener('click', function () {
      state.custom[otherMode()] = C.deriveCounterpart(state.custom[state.mode] || {}, state.mode);
      state.palette = '__custom';
      scheduleSave(); renderPalettes(); renderColors(); renderPreview(true);
      toast('Đã sinh bộ màu ' + (otherMode() === 'dark' ? 'tối' : 'sáng') + ' từ bộ đang sửa.');
    });
    $('btnCopyDark').addEventListener('click', function () {
      state.custom[otherMode()] = merge({}, state.custom[state.mode] || {});
      state.palette = '__custom';
      scheduleSave(); renderPalettes(); renderColors(); renderPreview(true);
      toast('Đã chép bộ màu sang chế độ còn lại.');
    });
    $('btnAppTheme').addEventListener('click', function () {
      var root = document.documentElement;
      var next = root.dataset.appTheme === 'light' ? 'dark' : 'light';
      root.dataset.appTheme = next;
      try { localStorage.setItem('doc-styler-app-theme', next); } catch (e) {}
    });

    ['dragenter', 'dragover'].forEach(function (ev) {
      window.addEventListener(ev, function (e) { e.preventDefault(); $('drop').className = 'on'; });
    });
    window.addEventListener('dragleave', function (e) {
      e.preventDefault();
      if (!e.relatedTarget) $('drop').className = '';
    });
    window.addEventListener('drop', function (e) {
      e.preventDefault();
      $('drop').className = '';
      Array.prototype.slice.call((e.dataTransfer || {}).files || []).forEach(function (f) {
        if (/\.html?$/i.test(f.name)) importTemplateFile(f);
        else importDocument(f);
      });
    });

    if (restored) toast('Đã khôi phục bản đang soạn dở.');
    /* ?demo=1 opens the editor with the sample document already loaded, which
       is how the layout is checked without retyping a document. */
    if (/[?&]demo/.test(location.search) && !restored) $('btnLoadSample').click();
  }

  try {
    var appTheme = localStorage.getItem('doc-styler-app-theme');
    if (appTheme) document.documentElement.dataset.appTheme = appTheme;
  } catch (e) {}

  state = blankState();
  function init() {
    boot();
    if (/[?&]selftest/.test(location.search)) selfTest();
    window.__docStyler = { state: function () { return state; }, buildDoc: buildDoc, core: C };
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();

