scripts/preview_sheet.py.text:
#!/usr/bin/env python3
"""Render one document through every template, side by side, so a template can
be chosen by looking rather than by reading manifests.

    python scripts/preview_sheet.py --model model.json \
        --templates assets/templates --out preview --palette slate

Writes preview-<template>.html per template plus an index.html that shows them
all as scaled thumbnails with a link to open each at full size. Add
--palette-matrix to give every card a row of palette buttons that repaint its
thumbnail in place, which is how a template-plus-colour is picked.

The index is self-contained (thumbnails are embedded, not loaded), so it opens
straight from file:// with no server and no network.
"""

from __future__ import annotations

import argparse
import io
import json
import re
import sys
from contextlib import redirect_stdout
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import render_doc as R  # noqa: E402

BODY_RE = re.compile(r"\{\{\s*body\s*\}\}")
BRAND_VARS = ("--brand-primary", "--brand-accent", "--brand-ink", "--doc-bg", "--doc-surface")


def find_templates(root):
    found = []
    for folder in sorted(p for p in Path(root).iterdir() if p.is_dir()):
        try:
            entry = R.find_entry(folder)
        except FileNotFoundError:
            continue
        manifest = {}
        mpath = folder / "manifest.json"
        if mpath.is_file():
            try:
                manifest = json.loads(mpath.read_text(encoding="utf-8-sig"))
            except json.JSONDecodeError:
                manifest = {}
        found.append({
            "id": manifest.get("id") or folder.name,
            "label": manifest.get("label") or folder.name,
            "use_when": manifest.get("use_when") or "",
            "default_palette": manifest.get("default_palette") or "",
            "folder": folder,
            "entry": entry,
        })
    return found


def js_json(value):
    text = json.dumps(value, ensure_ascii=False, indent=1)
    return text.replace("</", "<\\/").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")

