def load_palettes(path):
    try:
        return json.loads(Path(path).read_text(encoding="utf-8-sig")).get("palettes") or {}
    except (OSError, json.JSONDecodeError):
        return {}


def main(argv=None):
    parser = argparse.ArgumentParser(description="Render one model through every template for comparison.")
    parser.add_argument("--model", required=True)
    parser.add_argument("--templates", required=True, help="folder holding one directory per template")
    parser.add_argument("--out", required=True, help="output folder for the previews and index.html")
    parser.add_argument("--palette", default="", help="one palette applied to every template")
    parser.add_argument("--palette-file", default="")
    parser.add_argument("--palettes", default="", help="palettes.json path")
    parser.add_argument("--palette-matrix", default="",
                        help="comma-separated palette names, or 'all': every card gets one button per palette")
    parser.add_argument("--mode", choices=("auto", "dark", "light"), default="auto")
    args = parser.parse_args(argv)

    out = Path(args.out).expanduser()
    out.mkdir(parents=True, exist_ok=True)

    model_path = Path(args.model).expanduser()
    model = json.loads(model_path.read_text(encoding="utf-8-sig"))
    lang = R.plain(model.get("lang")) or "vi"

    palettes_path = Path(args.palettes).expanduser() if args.palettes else \
        Path(__file__).resolve().parent.parent / "assets" / "palettes.json"
    all_palettes = load_palettes(palettes_path)

    single = None
    palette_name = "template default"
    if args.palette_file:
        single = json.loads(Path(args.palette_file).expanduser().read_text(encoding="utf-8-sig"))
        palette_name = Path(args.palette_file).name
    elif args.palette:
        single = R.load_palette(args.palette, palettes_path)
        palette_name = args.palette

    matrix = []
    if args.palette_matrix:
        wanted = args.palette_matrix.strip()
        matrix = sorted(all_palettes) if wanted.lower() == "all" else \
            [p.strip() for p in wanted.split(",") if p.strip()]
        if not matrix:
            print("error: --palette-matrix selected no palette", file=sys.stderr)
            return 2
        unknown = [p for p in matrix if p not in all_palettes]
        if unknown:
            print("error: unknown palette(s): %s; available: %s"
                  % (", ".join(unknown), ", ".join(sorted(all_palettes))), file=sys.stderr)
            return 2

    mode = args.mode
    if mode == "auto":
        mode = (single or {}).get("default_mode") or "dark"

    def render(target, cli):
        buffer = io.StringIO()
        with redirect_stdout(buffer):
            code = R.main(cli)
        lines = buffer.getvalue().strip().splitlines()
        return code, (lines[-1] if lines else "")

    templates = find_templates(args.templates)
    if not templates:
        print("error: no template found in %s" % args.templates, file=sys.stderr)
        return 2

    cards = []
    for tpl in templates:
        entry_text = tpl["entry"].read_text(encoding="utf-8")
        placeholders = sorted(set(R.PLACEHOLDER_RE.findall(entry_text)))
        chips = []
        if not BODY_RE.search(entry_text):
            chips.append({"text": "khong co {{body}}", "cls": "no"})
        if any(v not in entry_text for v in BRAND_VARS):
            chips.append({"text": "mau co dinh", "cls": "no"})
        if not chips:
            chips.append({"text": "san sang", "cls": "ok"})
        chips.append({"text": str(len(placeholders)) + " placeholder", "cls": ""})

        specs = []
        if matrix:
            names = list(matrix)
            default_name = tpl["default_palette"]
            if default_name and default_name in names:
                # the template's own palette goes first, so the thumbnail
                # opens on the look the template was designed around
                names = [default_name] + [n for n in names if n != default_name]
            elif default_name:
                names = [default_name] + names
            for name in names:
                theme = args.mode if args.mode != "auto" else (all_palettes[name].get("default_mode") or "dark")
                label = name + ("  *" if name == tpl["default_palette"] else "")
                specs.append((label, "preview-%s-%s.html" % (tpl["id"], name), theme, ["--palette", name]))
        else:
            extra = []
            if args.palette_file:
                extra = ["--palette-file", args.palette_file]
            elif args.palette:
                extra = ["--palette", args.palette]
            specs.append((palette_name, "preview-%s.html" % tpl["id"], mode, extra))

        variants = []
        for label, filename, theme, extra in specs:
            target = out / filename
            cli = ["--model", str(model_path), "--template", str(tpl["folder"]),
                   "--out", str(target), "--theme", theme] + extra
            if args.palettes:
                cli += ["--palettes", args.palettes]
            code, _note = render(target, cli)
            if code != 0:
                print("error: rendering %s failed" % tpl["id"], file=sys.stderr)
                return code
            variants.append({
                "label": label, "theme": theme, "file": filename,
                "html": target.read_text(encoding="utf-8"),
            })
        if len(variants) > 1:
            chips.append({"text": str(len(variants)) + " mau", "cls": ""})
        cards.append({"id": tpl["id"], "label": tpl["label"], "use_when": tpl["use_when"],
                      "chips": chips, "variants": variants})
        print("  %-18s -> %d variant(s)" % (tpl["id"], len(variants)))

    title = R.plain(model.get("title"), lang) or "Tai lieu"
    if matrix:
        if args.mode == "auto":
            note = ("mỗi card một nút cho từng palette, chế độ lấy theo từng palette"
                    " (* = palette mặc định của template)")
        else:
            note = ("mỗi card một nút cho từng palette, chế độ <code>%s</code>"
                    " (* = palette mặc định của template)" % R.esc(mode))
    else:
        note = "palette <code>%s</code>, chế độ <code>%s</code>" % (R.esc(palette_name), R.esc(mode))
    page = (INDEX
            .replace("__TITLE__", R.esc(title))
            .replace("__SUBTITLE__", R.esc(R.plain(model.get("subtitle"), lang) or model_path.name))
            .replace("__N__", str(len(cards)))
            .replace("__VARIANTS__", note)
            .replace("__DATA__", js_json(cards)))
    index_path = out / "index.html"
    index_path.write_text(page, encoding="utf-8")

    print("\nwrote %s" % index_path)
    print("open it, then say which template + colour to use (or none, and give your own colour)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

