#!/usr/bin/env python3
"""Scan a folder of HTML templates and emit a machine-readable registry.

A template is any subfolder containing at least one .html file. If the folder
has a manifest.json it is used; otherwise metadata is inferred from the markup
(placeholders, CSS custom properties).
"""

from __future__ import annotations

import argparse
import json
import re
import sys
from pathlib import Path

REQUIRED_PLACEHOLDERS = ("title", "body")
REQUIRED_CSS_VARS = ("--brand-primary", "--brand-accent", "--brand-ink", "--doc-bg", "--doc-surface")
PLACEHOLDER_RE = re.compile(r"\{\{\s*([A-Za-z0-9_.-]+)\s*\}\}")
CSS_VAR_RE = re.compile(r"(--[A-Za-z0-9-]+)\s*:\s*([^;{}]+);")
TEXT_SUFFIXES = {".html", ".htm", ".css"}
PREFERRED_ENTRIES = ("template.html", "index.html", "template.htm", "index.htm")


def humanize(name):
    return name.replace("_", "-").strip("-").replace("-", " ").title()


def find_entry(folder, manifest):
    entry = manifest.get("entry")
    if entry:
        candidate = folder / entry
        return candidate if candidate.is_file() else None
    for name in PREFERRED_ENTRIES:
        candidate = folder / name
        if candidate.is_file():
            return candidate
    html_files = sorted(p for p in folder.rglob("*.htm*") if p.is_file())
    return html_files[0] if html_files else None


def read_manifest(folder):
    path = folder / "manifest.json"
    if not path.is_file():
        return {}
    try:
        return json.loads(path.read_text(encoding="utf-8-sig"))
    except json.JSONDecodeError as exc:
        return {"_manifest_error": str(exc)}


def scan_template(folder):
    manifest = read_manifest(folder)
    entry = find_entry(folder, manifest)

    chunks = []
    if entry:
        chunks.append(entry.read_text(encoding="utf-8", errors="replace"))
    for css in sorted(folder.rglob("*.css")):
        chunks.append(css.read_text(encoding="utf-8", errors="replace"))
    if entry:
        for other in sorted(folder.rglob("*.htm*")):
            if other != entry:
                chunks.append(other.read_text(encoding="utf-8", errors="replace"))
    text = "\n".join(chunks)

    placeholders = sorted(set(PLACEHOLDER_RE.findall(text)))
    css_vars = {}
    for name, value in CSS_VAR_RE.findall(text):
        css_vars.setdefault(name, value.strip())

    issues = []
    if manifest.get("_manifest_error"):
        issues.append("manifest.json is not valid JSON: " + manifest["_manifest_error"])
    if entry is None:
        issues.append("no .html entry file found")
    missing_ph = [p for p in REQUIRED_PLACEHOLDERS if p not in placeholders]
    if missing_ph:
        issues.append("missing required placeholder(s): " + ", ".join("{{%s}}" % p for p in missing_ph))
    missing_vars = [v for v in REQUIRED_CSS_VARS if v not in css_vars]
    if missing_vars:
        issues.append("missing colour variable(s): " + ", ".join(missing_vars))
    if re.search(r'(?:src|href)\s*=\s*["\']https?://', text, re.IGNORECASE):
        issues.append("loads an external http(s) resource (breaks offline file:// use)")

    folder_name = folder.name
    return {
        "id": manifest.get("id") or folder_name,
        "label": manifest.get("label") or humanize(folder_name),
        "description": manifest.get("description") or "",
        "use_when": manifest.get("use_when") or "",
        "doc_types": manifest.get("doc_types") or [],
        "default_palette": manifest.get("default_palette") or "",
        "entry": entry.relative_to(folder).as_posix() if entry else "",
        "placeholders": placeholders,
        "css_vars": css_vars,
        "path": str(folder),
        "issues": issues,
    }


def main(argv=None):
    parser = argparse.ArgumentParser(description="Scan HTML templates into a registry.")
    parser.add_argument("templates_dir", help="folder holding one subfolder per template")
    parser.add_argument("--out", help="write the registry JSON here instead of stdout")
    args = parser.parse_args(argv)

    root = Path(args.templates_dir).expanduser()
    if not root.is_dir():
        print("error: not a directory: %s" % root, file=sys.stderr)
        return 2

    templates = []
    for child in sorted(p for p in root.iterdir() if p.is_dir()):
        if any(f.suffix.lower() in {".html", ".htm"} for f in child.rglob("*")):
            templates.append(scan_template(child))

    registry = {"templates_dir": str(root), "templates": templates}
    payload = json.dumps(registry, indent=2, ensure_ascii=False)

    if args.out:
        Path(args.out).write_text(payload + "\n", encoding="utf-8")
        print("wrote %d template(s) to %s" % (len(templates), args.out))
    else:
        print(payload)

    blocked = [t["id"] for t in templates if t["issues"]]
    if blocked:
        print("templates with issues: %s" % ", ".join(blocked), file=sys.stderr)
    if not templates:
        print("warning: no templates found in %s" % root, file=sys.stderr)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

