#!/usr/bin/env node
/* Test suite for the editor's shared logic.
 *
 * The rendering tests compare against assets/editor/src/golden.json, which
 * scripts/build_editor.py generates with render_doc.py - so this checks the JS
 * renderer against the Python one instead of against itself. Everything else
 * (parsers, colours, template adaptation) is asserted directly.
 *
 *   node scripts/test_editor.mjs
 */

import fs from 'node:fs';
import path from 'node:path';
import url from 'node:url';

const here = path.dirname(url.fileURLToPath(import.meta.url));
const ROOT = path.join(here, '..');
const SRC = path.join(ROOT, 'assets', 'editor', 'src');

const core = new Function(
  fs.readFileSync(path.join(SRC, 'core.js'), 'utf8') + '\nreturn globalThis.DocStylerCore;'
)();
const fixture = JSON.parse(fs.readFileSync(path.join(SRC, 'fixture-model.json'), 'utf8'));
const golden = JSON.parse(fs.readFileSync(path.join(SRC, 'golden.json'), 'utf8'));
const palettes = JSON.parse(fs.readFileSync(path.join(ROOT, 'assets', 'palettes.json'), 'utf8')).palettes;

let passed = 0;
const failures = [];

function check(name, fn) {
  try {
    const result = fn();
    if (result === true) { passed++; return; }
    failures.push(name + ' -> ' + result);
  } catch (err) {
    failures.push(name + ' -> threw: ' + err.message);
  }
}

function sameString(name, actual, expected) {
  check(name, () => {
    if (actual === expected) return true;
    for (let i = 0; i < Math.max(actual.length, expected.length); i++) {
      if (actual[i] !== expected[i]) {
        return 'differs at char ' + i
          + '\n      golden: ' + JSON.stringify(expected.slice(Math.max(0, i - 50), i + 50))
          + '\n      actual: ' + JSON.stringify(actual.slice(Math.max(0, i - 50), i + 50));
      }
    }
    return 'length ' + actual.length + ' vs golden ' + expected.length;
  });
}

/* ---- parity with render_doc.py ---- */

sameString('renderSections matches render_doc.py', core.renderSections(fixture.sections), golden.sections);
sameString('renderToc matches render_doc.py', core.renderToc(fixture.sections), golden.toc);
sameString('renderBlocks matches render_doc.py', core.renderBlocks(fixture.sections[1].blocks), golden.blocks);
sameString('paletteStyle matches render_doc.py', core.paletteStyle(palettes['warm-earth'], 'light'), golden.palette);

/* ---- markdown parsing ---- */

check('markdown: first h1 becomes the title', () => {
  const m = core.parseMarkdown('# Bao cao quy 3\n\n## Muc\n\nNoi dung.\n');
  return m.title === 'Bao cao quy 3' || 'title=' + JSON.stringify(m.title);
});

check('markdown: h2 starts a section, h3 becomes a block', () => {
  const m = core.parseMarkdown('# T\n\n## A\n\n### A.1\n\nx\n\n## B\n\ny\n');
  if (m.sections.length !== 2) return 'sections=' + m.sections.length;
  const second = m.sections[0].blocks[0];
  return (second.type === 'heading' && second.level === 3) || 'got ' + JSON.stringify(second);
});

check('markdown: pipe table becomes a table block', () => {
  const m = core.parseMarkdown('# T\n\n| A | B |\n|---|---|\n| 1 | 2 |\n');
  const b = m.sections[0].blocks[0];
  if (b.type !== 'table') return 'got ' + b.type;
  if (b.headers.join('|') !== 'A|B') return 'headers=' + JSON.stringify(b.headers);
  return b.rows.length === 1 && b.rows[0].join('|') === '1|2' || 'rows=' + JSON.stringify(b.rows);
});

check('markdown: bullets and numbers become lists', () => {
  const ul = core.parseMarkdown('# T\n\n- a\n- b\n').sections[0].blocks[0];
  const ol = core.parseMarkdown('# T\n\n1. a\n2. b\n').sections[0].blocks[0];
  if (ul.type !== 'list' || ul.ordered) return 'unordered list wrong: ' + JSON.stringify(ul);
  if (ol.type !== 'list' || !ol.ordered) return 'ordered list wrong: ' + JSON.stringify(ol);
  return ul.items.length === 2 && ol.items.length === 2 || 'item counts differ';
});

check('markdown: Key: Value lines become kv', () => {
  const m = core.parseMarkdown('# T\n\nNguoi lap: Trung\nDon vi: Kinh doanh\n');
  const b = m.sections[0].blocks[0];
  return (b.type === 'kv' && b.pairs.length === 2) || 'got ' + JSON.stringify(b);
});

check('markdown: blockquote becomes a quote', () => {
  const m = core.parseMarkdown('# T\n\n> Cau trich.\n');
  const b = m.sections[0].blocks[0];
  return (b.type === 'quote' && b.text === 'Cau trich.') || 'got ' + JSON.stringify(b);
});

check('markdown: a paragraph with one pipe is not a table', () => {
  const m = core.parseMarkdown('# T\n\nThe a | b ratio is fine.\n');
  const b = m.sections[0].blocks[0];
  return (b.type === 'paragraph' && b.text.indexOf('ratio') > 0) || 'got ' + JSON.stringify(b);
});

check('markdown: blank input yields an empty model', () => {
  const m = core.parseMarkdown('');
  return (m.sections.length === 0 && m.title === '') || 'got ' + JSON.stringify(m);
});

/* ---- template handling ---- */

const templates = fs.readdirSync(path.join(ROOT, 'assets', 'templates'), { withFileTypes: true })
  .filter((d) => d.isDirectory())
  .map((d) => ({ id: d.name, html: fs.readFileSync(path.join(ROOT, 'assets', 'templates', d.name, 'template.html'), 'utf8') }));

check('two built-in templates ship with the skill', () => {
  return templates.length >= 2 || 'found ' + templates.map((t) => t.id).join(', ');
});

for (const tpl of templates) {
  check('fillTemplate leaves no placeholder unfilled: ' + tpl.id, () => {
    const out = core.fillTemplate(tpl.html, core.sampleModel(), { palette: palettes['technext'] });
    return out.leftover.length === 0 || 'leftover ' + out.leftover.join(', ');
  });
  check('fillTemplate injects both theme rules: ' + tpl.id, () => {
    const out = core.fillTemplate(tpl.html, core.sampleModel(), { palette: palettes['warm-earth'], theme: 'light' });
    const i = out.html.indexOf('palette-override');
    if (i < 0) return 'no palette-override style block';
    const seg = out.html.slice(i, i + 1200);
    if (!seg.includes('html[data-theme="dark"]')) return 'no dark attribute rule';
    if (!seg.includes('html[data-theme="light"]')) return 'no light attribute rule';
    return seg.includes(palettes['warm-earth'].modes.light['--brand-primary']) || 'light primary not present';
  });
  check('fillTemplate is offline-safe: ' + tpl.id, () => {
    const out = core.fillTemplate(tpl.html, core.sampleModel(), { palette: palettes['technext'] });
    const external = out.html.match(/(?:src|href)\s*=\s*["']https?:\/\//gi) || [];
    return external.length === 0 || 'found ' + external.length + ' external reference(s)';
  });
}

check('inspectTemplate detects a usable template', () => {
  const info = core.inspectTemplate(templates[0].html);
  return (info.hasBody && info.themeable) || JSON.stringify(info);
});

check('inspectTemplate flags an ordinary page', () => {
  const info = core.inspectTemplate('<!DOCTYPE html><html><body><h1>Hi</h1></body></html>');
  return (!info.hasBody && !info.themeable) || JSON.stringify(info);
});

check('adaptTemplate gives an ordinary page a body slot', () => {
  const adapted = core.adaptTemplate('<!DOCTYPE html><html><head></head><body><h1>Hi</h1></body></html>');
  const info = core.inspectTemplate(adapted);
  return info.hasBody || 'still no {{body}}';
});

/* ---- colours ---- */

check('deriveCounterpart returns usable hex for every var', () => {
  const out = core.deriveCounterpart(palettes['technext'].modes.dark, 'dark');
  const bad = Object.keys(out).filter((k) => !core.hexToRgb(out[k]));
  return bad.length === 0 || 'bad values for ' + bad.join(', ');
});

check('deriveCounterpart actually changes the mode', () => {
  const dark = palettes['technext'].modes.dark;
  const light = core.deriveCounterpart(dark, 'dark');
  return light['--doc-bg'] !== dark['--doc-bg'] || 'light bg identical to dark bg';
});

check('custom palette reaches the rendered document', () => {
  const pal = { default_mode: 'dark', modes: { dark: { '--brand-primary': '#ff0000' }, light: { '--brand-primary': '#00ff00' } } };
  const out = core.fillTemplate(templates[0].html, core.sampleModel(), { palette: pal, theme: 'dark' });
  return out.html.includes('#ff0000') || 'custom colour missing from output';
});

/* ---- model hygiene ---- */

check('normalizeModel tolerates junk', () => {
  const m = core.normalizeModel({ sections: [{ heading: 'A', blocks: [{ type: 'table' }, null, 'nope'] }, null] });
  if (m.sections.length !== 1) return 'sections=' + m.sections.length;
  if (m.sections[0].blocks.length !== 1) return 'blocks=' + m.sections[0].blocks.length;
  const b = m.sections[0].blocks[0];
  return (b.type === 'table' && Array.isArray(b.rows) && Array.isArray(b.headers)) || JSON.stringify(b);
});

check('bilingual detection sees a dual field', () => {
  if (!core.hasDual({ title: { vi: 'a', en: 'b' } })) return 'mixed dual not detected';
  if (core.hasDual({ title: 'a' })) return 'plain string reported as dual';
  return true;
});

check('escaping covers markup and quotes', () => {
  const out = core.rt('<b>&"x"</b>');
  return out === '&lt;b&gt;&amp;&quot;x&quot;&lt;/b&gt;' || 'got ' + out;
});

/* ---- report ---- */

const total = passed + failures.length;
if (failures.length) {
  console.log('FAILED ' + failures.length + '/' + total);
  failures.forEach((f) => console.log('  FAIL  ' + f));
  process.exit(1);
}
console.log('all ' + total + ' checks passed');
